$counts=[]; foreach (rows('SELECT status,COUNT(*) n FROM requests WHERE user_id=? GROUP BY status',[$u['id']]) as $c) $counts[$c['status']]=$c['n'];
$semester=date('Y').'-'.((int)date('m')<=6?'1':'2'); $used=$wf->quota((int)$u['id'],$semester);
$pending=(int)(row("SELECT COUNT(*) n FROM approvals a JOIN requests r ON r.id=a.request_id WHERE a.assigned_user_id=? AND a.status='waiting' AND r.status='pending' AND a.revision=r.revision AND NOT EXISTS(SELECT 1 FROM approvals b WHERE b.request_id=a.request_id AND b.revision=a.revision AND b.step<a.step AND b.status='waiting')",[$u['id']])['n']);
$recent=rows('SELECT r.*,c.name category,c.family FROM requests r JOIN categories c ON c.id=r.category_id WHERE r.user_id=? ORDER BY r.id DESC LIMIT 5',[$u['id']]);
?>
